preConditionHook:
// At least minCount of the last lookback bars are with-trend trend bars that
// are ALSO large -- a high-low range of at least largeMultiple times the ATR.
//
// The conjunction sits INSIDE the count on purpose: 'two large bull trend bars
// in the last six' is not 'two bull trend bars in the last six' ANDed with
// 'two large bars in the last six', which two separate count panes could
// satisfy with two different bars. That is why this is kept apart from
// TrendBarCountInWindow, LargeBarCountInWindow and BarRangeAboveAtrMultiple.
//
// Written as an explicit loop rather than CountIF because the size benchmark
// is a FUNCTION value, and a function-history reference nested inside a
// CountIF's true-series argument is not a behaviour the register covers -- the
// same call LargeTailedBarCount makes. The benchmark is deliberately the
// CURRENT bar's ATR held fixed across the counted window, so the loop counts
// bars 0..lookback-1 current-inclusive exactly as CountIF would.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget and ClimaxBar, including the TWO
// separate accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently and lands on the other side of a threshold.
// It stays in the hook, which the generator emits unconditionally: EL does not
// short-circuit and/or, so an accumulator in a condition would advance every
// bar in EL and only on some bars in C++.
//
// Deepest bar read is the larger of lookback - 1 and atrLookback + 1.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
bigBullBars = 0.0;
bigBearBars = 0.0;
for (kk = 0; kk < (int)lookback; ++kk) {
    if (el_gt(close[kk], open[kk])
        && el_ge(close[kk] - open[kk], bodyFraction * (high[kk] - low[kk]))
        && el_ge(high[kk] - low[kk], largeMultiple * atrValue)) {
        bigBullBars += 1;
    }
    if (el_lt(close[kk], open[kk])
        && el_ge(open[kk] - close[kk], bodyFraction * (high[kk] - low[kk]))
        && el_ge(high[kk] - low[kk], largeMultiple * atrValue)) {
        bigBearBars += 1;
    }
}
